'use strict';
const activities=[{name:'제자리 걷기',tip:'한 발씩 번갈아 들며 작게 걸어요. 발을 들 공간과 소음을 살펴봐요.'},{name:'목·어깨 움직이기',tip:'편한 범위에서 천천히 움직여요. 아프거나 어지러우면 멈춰요.'},{name:'손목·손가락 움직이기',tip:'손목을 천천히 돌리거나 손가락을 접었다 펴요. 작은 공간에서도 할 수 있어요.'},{name:'앉아서 다리 들었다 내리기',tip:'바퀴가 없고 흔들리지 않는 의자에 앉아, 의자를 잡고 다리를 조금 들었다 내려요.'}];
const scenes=[{title:'숙제를 마친 뒤',text:'방에서 짧은 영상을 보고 있어요. 영상 보는 시간의 일부를 몸을 움직이는 데 써 보고 싶어요.',condition:'방이 좁고, 아래층에 소음이 들리지 않게 해야 해요.',change:'다리를 움직이니 불편해졌어요. 어떻게 할까요?'},{title:'친구의 연락을 기다릴 때',text:'답장이 왔는지 자꾸 휴대전화를 확인해요. 연락을 기다리는 동안 잠깐 몸을 움직여 보려고 해요.',condition:'거실에 튼튼한 의자가 있어요. 필요한 연락은 확인할 수 있어야 해요.',change:'의자를 다른 곳으로 옮겨서 쓸 수 없어요. 어떻게 할까요?'},{title:'게임을 잠깐 쉬는 시간',text:'게임을 하다가 쉬는 시간이 되었어요. 계속 앉아 있었으니 잠깐 움직이고 싶어요.',condition:'책상 옆에 서 있을 공간은 있어요. 큰 소리를 내지 않고 할 활동을 골라요.',change:'오늘은 몸이 불편해서 움직이기 어려워요. 어떻게 할까요?'}];
const reasons=['작은 공간에서도 할 수 있어서','소리가 적어서','내 몸이 편하게 할 수 있어서','필요한 물건이 있어서'];
let round=0,phase='choose',selected=null,reason='',adapt='',answers=[];
const stage=document.querySelector('#stage');
function el(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e}
function button(text,fn,cls){const b=el('button',text,cls);b.type='button';b.addEventListener('click',fn);return b}
function render(){stage.replaceChildren();document.querySelector('#progress').replaceChildren(...scenes.map((_,i)=>el('span','',i<=round?'dot active':'dot')));if(phase==='done'){finish();return}const s=scenes[round];stage.append(el('p',`${round+1} / 3 · ${s.title}`,'badge'),el('h2',phase==='choose'?'어떤 움직임을 골라 볼까요?':'상황이 달라지면 어떻게 할까요?'),el('p',phase==='choose'?s.text:s.change,'scene'));
if(phase==='choose'){stage.append(el('p',s.condition,'conditions'));const choices=el('div','','choices');activities.forEach((a,i)=>{const b=button(a.name,()=>{selected=i;render()});b.setAttribute('aria-pressed',String(selected===i));choices.append(b)});stage.append(choices);if(selected!==null){stage.append(el('p',activities[selected].tip,'feedback'),el('label','이 활동을 고른 이유는 무엇인가요?'));const rs=el('div','','choices');reasons.forEach(r=>{const b=button(r,()=>{reason=r;render()});b.setAttribute('aria-pressed',String(reason===r));rs.append(b)});stage.append(rs)}const next=button('조건이 바뀌면? →',()=>{phase='adapt';render()},'primary');next.disabled=selected===null||!reason;stage.append(next)}
else{const opts=round===1?['의자가 필요 없는 활동으로 바꿔요','의자를 쓸 수 있는 때에 해요']:['불편한 동작을 멈추고 쉬어요','편하게 할 수 있는 다른 활동이 있는지 살펴봐요'];const choices=el('div','','choices');opts.forEach(t=>{const b=button(t,()=>{adapt=t;render()});b.setAttribute('aria-pressed',String(adapt===t));choices.append(b)});stage.append(choices);if(adapt)stage.append(el('p',round===1?'활동에 필요한 물건이 없다면 방법이나 때를 바꿀 수 있어요.': '몸이 불편하면 먼저 멈추고 쉬어요. 다른 활동도 편하게 할 수 있을 때만 해요.','feedback'));const next=button(round===2?'내 선택 돌아보기 →':'다음 상황 →',()=>{answers.push({scene:s.title,activity:activities[selected].name,reason,adapt});round++;selected=null;reason='';adapt='';phase=round===3?'done':'choose';render();stage.scrollIntoView({behavior:'smooth',block:'start'})},'primary');next.disabled=!adapt;stage.append(next)}
}
function finish(){stage.append(el('p','3개 상황을 살펴봤어요','badge'),el('h2','이제 내 생활에 맞게 골라요'),el('p','같은 활동도 장소와 몸 상태에 따라 선택이 달라질 수 있어요.','scene'));answers.forEach(a=>stage.append(el('div',`${a.scene} · ${a.activity}\n선택 이유: ${a.reason}\n상황이 달라지면: ${a.adapt}`,'result')));const label=el('label','나는 어떤 상황에서 어떤 움직임을 해 볼까요?');label.htmlFor='myChoice';const input=el('textarea');input.id='myChoice';input.maxLength=400;input.placeholder='예: 숙제를 마친 뒤 방에서 손가락을 접었다 펴고 싶어요. 조용하게 할 수 있어서예요.';stage.append(label,input,el('p','워크북 4쪽의 내 습관을 떠올리고, 5쪽에 활동 하나와 선택 이유를 적어요. 언제 시작하고 얼마나 할지는 3차시에서 정해요.','feedback'),el('p','이 칸은 생각을 정리하는 메모예요. 저장하거나 전송하지 않아요.','small'));const actions=el('div','','actions');actions.append(button('다시 해 보기',()=>{round=0;phase='choose';selected=null;reason='';adapt='';answers=[];render()},'primary'),button('내 선택 인쇄하기',()=>window.print()));stage.append(actions)}
render();
